def peekn(seq, n):
    """Retrieve the first *n* elements of a sequence.

    Returns a tuple of the first *n* items and an iterable that yields
    those items again followed by the rest of the original sequence.

    Raises ``StopIteration`` if the sequence contains fewer than *n*
    elements.
    """
    iterator = iter(seq)
    first_n = tuple(itertools.islice(iterator, n))
    if len(first_n) < n:
        raise StopIteration
    return first_n, itertools.chain(first_n, iterator)
